nomed("nitazenes", "Nitazenes", ["Benzimidazole-opioids", "Isotonitazene", "Protonitazene", "Metonitazene", "N-pyrrolidino etonitazene"], C, "Synthetic opioids (benzimidazole-opioids)", "I",
      description="Nitazenes facts: a class of synthetic opioids that can be stronger than fentanyl, overdose and naloxone, test strips, DEA Schedule I actions, and how to stay safer.",
      quick="Nitazenes are a group of synthetic opioids, first made in the 1950s but never approved as medicines, that have appeared in the illicit drug supply since 2019. Some are many times stronger than fentanyl. They are found in fake pills and powders, are not detected by fentanyl test strips, and can need several doses of naloxone. Many are in Schedule I.",
      facts=[["Chemical class", "2-benzylbenzimidazole opioids"], ["Examples", "Isotonitazene, metonitazene, protonitazene, N-pyrrolidino etonitazene (etonitazepyne)"], ["Drug class", "Synthetic mu-opioid agonists"],
             ["US legal status", "Many permanently or temporarily Schedule I; new variants appear"], ["Medical use", "None"], ["Potency", "Varies; some exceed fentanyl"],
             ["Found in", "Counterfeit pills (oxycodone, benzodiazepines), powders, heroin and fentanyl"], ["Detected by fentanyl strips", "No; separate nitazene strips exist"], ["Onset", "Minutes"], ["Reversal agent", "Naloxone; multiple doses may be needed"]],
      profile=P("Minutes", "Hours (varies)", "Varies by compound", "Yes, multiple doses may be needed", "Very high", "None", ["opioid"]),
      what={"blocks": ["Nitazenes were developed by a Swiss drug company in the 1950s as possible pain medicines but were never approved because of their danger. Since 2019, illicit manufacturers have produced dozens of variants.[[dea_nitaz]]",
                       "They are sold as powders or pressed into counterfeit pills made to look like oxycodone or benzodiazepines, and are sometimes mixed into heroin or fentanyl. Buyers usually do not know they are taking them."]},
      effects={"blocks": ["Nitazenes cause typical opioid effects: euphoria, drowsiness, pinpoint pupils, and slowed breathing. Because some are extremely potent and doses are unpredictable, the gap between a sedating dose and a fatal one can be tiny.[[dea_nitaz]]"]},
      risks=[{"p": "**Overdose:** nitazenes have caused clusters of overdose deaths in the US, UK, and elsewhere. Some, such as etonitazene and N-pyrrolidino etonitazene, are many times more potent than fentanyl.[[dea_nitaz]]"},
             {"p": "**Hidden in pills:** they have been found in fake pills sold as oxycodone, Xanax, and other medicines, affecting people with no opioid tolerance."},
             {"p": "**Testing:** fentanyl test strips do not detect nitazenes. Nitazene-specific test strips are available in some areas."}],
      interactions=[["Benzodiazepines, including fake Xanax", "Deep sedation, stopped breathing", "Very high risk"], ["Alcohol", "Additive breathing suppression", "Very high risk"],
                    ["Fentanyl, heroin, other opioids", "Extreme overdose risk", "Very high risk"], ["Xylazine", "Deeper sedation not reversed by naloxone", "Very high risk"]],
      overdose={"kind": "opioid", "q": "What does a nitazene overdose look like?", "signs": "Nitazene overdose looks like any opioid overdose: pinpoint pupils, unresponsiveness, slow or stopped breathing, and blue or gray lips. It can come on fast and be very deep.[[dea_nitaz]][[naloxone]]",
                "after": ["Give naloxone and repeat every 2 to 3 minutes if there is no response. Some nitazene overdoses need several doses, and the effects can outlast naloxone, so the person needs emergency care and monitoring."]},
      dependence={"blocks": [{"p": "Nitazenes cause opioid dependence and withdrawal like other potent opioids.[[dea_nitaz]]"},
                             {"timeline": [{"when": "6 to 12 hours", "title": "Early withdrawal", "text": "Anxiety, sweating, runny nose, muscle aches."}, {"when": "Days 1 to 3", "title": "Peak", "text": "Vomiting, diarrhea, cramps, insomnia, cravings."}, {"when": "Days 5 to 10", "title": "Lingering", "text": "Fatigue, low mood, cravings."}]},
                             {"p": "Buprenorphine and methadone treat dependence on nitazenes as they do for other opioids."}]},
      legal_us={"blocks": [
          {"p": "Nitazenes have no accepted medical use. The DEA has placed many in Schedule I, some permanently and others by temporary emergency order; in October 2025 it temporarily added seven more variants through October 2027. Congress has considered bills to schedule the entire class at once.[[fr_nitaz]][[dea_nitaz]]"},
          penalties_block("nitazenes"),
          {"p": "**Analogues:** unscheduled variants sold for human consumption can be prosecuted as controlled substance analogues under the Federal Analogue Act."}]},
      help_extra=[{"p": "Medicines for opioid use disorder work for people exposed to nitazenes. Buprenorphine can be started by telemedicine.[[bup_tele]]"}],
      intl_rows=[["United Kingdom", "Class A (many named compounds)"], ["European Union", "Monitored by the EU Drugs Agency; controlled in member states"], ["International", "Several, including isotonitazene and metonitazene, in Schedule I of the 1961 Single Convention"]],
      faq=[["Are nitazenes stronger than fentanyl?", "Some are. Potency varies widely by compound, and several are many times stronger than fentanyl."],
           ["Does naloxone work on nitazenes?", "Yes, but more doses may be needed. Keep giving naloxone every 2 to 3 minutes and call 911."],
           ["Do fentanyl test strips detect nitazenes?", "No. Separate nitazene test strips are available in some areas."],
           ["Where are nitazenes found?", "In counterfeit pills, powders sold as heroin or fentanyl, and sometimes other drugs. Pills not from a pharmacy can contain them."]],
      src=SRC, guidance_head="Risk level")

